'use strict';

/**
* Return a reduced shape of a provided ndarray.
*
* @module @stdlib/ndarray/base/reduced-shape
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
* var reducedShape = require( '@stdlib/ndarray/base/reduced-shape' );
*
* var x = zeros( [ 3, 2, 3 ] );
* // returns <ndarray>
*
* var sh = reducedShape( x, [ 0, 1 ] );
* // returns [ 3 ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
